ALTER TABLE raids ADD COLUMN revision INTEGER NOT NULL DEFAULT 1;
CREATE TABLE raid_deletions (id TEXT PRIMARY KEY,raid_id TEXT NOT NULL UNIQUE,raid_name TEXT NOT NULL,raid_date TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL,summary_json TEXT NOT NULL,created_at TEXT NOT NULL,idempotency_key TEXT NOT NULL,request_signature TEXT NOT NULL,UNIQUE(actor_id,idempotency_key));
CREATE TRIGGER raid_deletions_immutable_update BEFORE UPDATE ON raid_deletions BEGIN SELECT RAISE(ABORT,'RAID_DELETION_IMMUTABLE'); END;
CREATE TRIGGER raid_deletions_immutable_delete BEFORE DELETE ON raid_deletions BEGIN SELECT RAISE(ABORT,'RAID_DELETION_IMMUTABLE'); END;
CREATE TABLE raid_delete_context (operation_id TEXT PRIMARY KEY,raid_id TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id));
CREATE VIEW raid_deletion_auctions AS SELECT d.raid_id,i.auction_id AS auction_id FROM loot_draft_items i JOIN loot_drafts d ON d.id=i.draft_id WHERE d.raid_id IS NOT NULL AND i.auction_id IS NOT NULL;
CREATE VIEW raid_deletion_ledger AS SELECT t.raid_id,l.id AS ledger_id,l.character_id,l.amount FROM ledger l JOIN attendance a ON a.id=l.attendance_id JOIN ticks t ON t.id=a.tick_id UNION SELECT d.raid_id,l.id,l.character_id,l.amount FROM ledger l JOIN auction_awards w ON w.ledger_id=l.id JOIN raid_deletion_auctions d ON d.auction_id=w.auction_id;
CREATE TRIGGER raid_delete_context_permission BEFORE INSERT ON raid_delete_context WHEN NOT EXISTS(SELECT 1 FROM access_effective_permissions a WHERE a.user_id=NEW.actor_id AND json_type(a.permissions_json,'$.attendance')='integer' AND json_extract(a.permissions_json,'$.attendance')=3) BEGIN SELECT RAISE(ABORT,'ACCESS_DENIED'); END;
CREATE TRIGGER raid_delete_context_balance BEFORE INSERT ON raid_delete_context WHEN EXISTS(SELECT l.character_id FROM ledger l WHERE l.character_id IN(SELECT character_id FROM raid_deletion_ledger WHERE raid_id=NEW.raid_id) AND l.id NOT IN(SELECT ledger_id FROM raid_deletion_ledger WHERE raid_id=NEW.raid_id) GROUP BY l.character_id HAVING SUM(l.amount) NOT BETWEEN -9007199254740991 AND 9007199254740991) BEGIN SELECT RAISE(ABORT,'RAID_DELETE_DKP_RANGE'); END;
DROP TRIGGER attendance_tick_clones_immutable_delete;
CREATE TRIGGER attendance_tick_clones_immutable_delete BEFORE DELETE ON attendance_tick_clones WHEN NOT EXISTS(SELECT 1 FROM raid_delete_context x WHERE x.raid_id=OLD.raid_id) BEGIN SELECT RAISE(ABORT,'ATTENDANCE_CLONE_IMMUTABLE'); END;
DROP TRIGGER auction_admin_actions_immutable_delete;
CREATE TRIGGER auction_admin_actions_immutable_delete BEFORE DELETE ON auction_admin_actions WHEN NOT EXISTS(SELECT 1 FROM raid_delete_context x JOIN raid_deletion_auctions a ON a.raid_id=x.raid_id WHERE a.auction_id=OLD.auction_id) BEGIN SELECT RAISE(ABORT,'AUCTION_ADMIN_IMMUTABLE'); END;
CREATE TRIGGER raid_revision_metadata AFTER UPDATE OF name,date,rate ON raids BEGIN UPDATE raids SET revision=revision+1 WHERE id=NEW.id; END;
CREATE TRIGGER raid_revision_ticks_insert AFTER INSERT ON ticks BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT NEW.raid_id); END;
CREATE TRIGGER raid_revision_ticks_update AFTER UPDATE ON ticks BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT OLD.raid_id UNION SELECT NEW.raid_id); END;
CREATE TRIGGER raid_revision_ticks_delete AFTER DELETE ON ticks BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT OLD.raid_id); END;
CREATE TRIGGER raid_revision_attendance_insert AFTER INSERT ON attendance BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM ticks WHERE id=NEW.tick_id); END;
CREATE TRIGGER raid_revision_attendance_update AFTER UPDATE ON attendance BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM ticks WHERE id=OLD.tick_id UNION SELECT raid_id FROM ticks WHERE id=NEW.tick_id); END;
CREATE TRIGGER raid_revision_attendance_delete AFTER DELETE ON attendance BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM ticks WHERE id=OLD.tick_id); END;
CREATE TRIGGER raid_revision_ledger_insert AFTER INSERT ON ledger BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT t.raid_id FROM attendance a JOIN ticks t ON t.id=a.tick_id WHERE a.id=NEW.attendance_id UNION SELECT d.raid_id FROM auction_awards w JOIN raid_deletion_auctions d ON d.auction_id=w.auction_id WHERE w.ledger_id=NEW.id); END;
CREATE TRIGGER raid_revision_ledger_update AFTER UPDATE ON ledger BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT t.raid_id FROM attendance a JOIN ticks t ON t.id=a.tick_id WHERE a.id=OLD.attendance_id UNION SELECT d.raid_id FROM auction_awards w JOIN raid_deletion_auctions d ON d.auction_id=w.auction_id WHERE w.ledger_id=OLD.id UNION SELECT t.raid_id FROM attendance a JOIN ticks t ON t.id=a.tick_id WHERE a.id=NEW.attendance_id UNION SELECT d.raid_id FROM auction_awards w JOIN raid_deletion_auctions d ON d.auction_id=w.auction_id WHERE w.ledger_id=NEW.id); END;
CREATE TRIGGER raid_revision_ledger_delete AFTER DELETE ON ledger BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT t.raid_id FROM attendance a JOIN ticks t ON t.id=a.tick_id WHERE a.id=OLD.attendance_id UNION SELECT d.raid_id FROM auction_awards w JOIN raid_deletion_auctions d ON d.auction_id=w.auction_id WHERE w.ledger_id=OLD.id); END;
CREATE TRIGGER raid_revision_correction_requests_insert AFTER INSERT ON correction_requests BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM ticks WHERE id=NEW.tick_id); END;
CREATE TRIGGER raid_revision_correction_requests_update AFTER UPDATE ON correction_requests BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM ticks WHERE id=OLD.tick_id UNION SELECT raid_id FROM ticks WHERE id=NEW.tick_id); END;
CREATE TRIGGER raid_revision_correction_requests_delete AFTER DELETE ON correction_requests BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM ticks WHERE id=OLD.tick_id); END;
CREATE TRIGGER raid_revision_loot_drafts_insert AFTER INSERT ON loot_drafts BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT NEW.raid_id); END;
CREATE TRIGGER raid_revision_loot_drafts_update AFTER UPDATE ON loot_drafts BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT OLD.raid_id UNION SELECT NEW.raid_id); END;
CREATE TRIGGER raid_revision_loot_drafts_delete AFTER DELETE ON loot_drafts BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT OLD.raid_id); END;
CREATE TRIGGER raid_revision_loot_draft_items_insert AFTER INSERT ON loot_draft_items BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM loot_drafts WHERE id=NEW.draft_id); END;
CREATE TRIGGER raid_revision_loot_draft_items_update AFTER UPDATE ON loot_draft_items BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM loot_drafts WHERE id=OLD.draft_id UNION SELECT raid_id FROM loot_drafts WHERE id=NEW.draft_id); END;
CREATE TRIGGER raid_revision_loot_draft_items_delete AFTER DELETE ON loot_draft_items BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM loot_drafts WHERE id=OLD.draft_id); END;
CREATE TRIGGER raid_revision_auctions_insert AFTER INSERT ON auctions BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=NEW.id); END;
CREATE TRIGGER raid_revision_auctions_update AFTER UPDATE ON auctions BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=OLD.id UNION SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=NEW.id); END;
CREATE TRIGGER raid_revision_auctions_delete AFTER DELETE ON auctions BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=OLD.id); END;
CREATE TRIGGER raid_revision_auction_bids_insert AFTER INSERT ON auction_bids BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=NEW.auction_id); END;
CREATE TRIGGER raid_revision_auction_bids_update AFTER UPDATE ON auction_bids BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=OLD.auction_id UNION SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=NEW.auction_id); END;
CREATE TRIGGER raid_revision_auction_bids_delete AFTER DELETE ON auction_bids BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=OLD.auction_id); END;
CREATE TRIGGER raid_revision_auction_bid_events_insert AFTER INSERT ON auction_bid_events BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=NEW.auction_id); END;
CREATE TRIGGER raid_revision_auction_bid_events_update AFTER UPDATE ON auction_bid_events BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=OLD.auction_id UNION SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=NEW.auction_id); END;
CREATE TRIGGER raid_revision_auction_bid_events_delete AFTER DELETE ON auction_bid_events BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=OLD.auction_id); END;
CREATE TRIGGER raid_revision_auction_awards_insert AFTER INSERT ON auction_awards BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=NEW.auction_id); END;
CREATE TRIGGER raid_revision_auction_awards_update AFTER UPDATE ON auction_awards BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=OLD.auction_id UNION SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=NEW.auction_id); END;
CREATE TRIGGER raid_revision_auction_awards_delete AFTER DELETE ON auction_awards BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=OLD.auction_id); END;
CREATE TRIGGER raid_revision_auction_admin_actions_insert AFTER INSERT ON auction_admin_actions BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=NEW.auction_id); END;
CREATE TRIGGER raid_revision_auction_admin_actions_update AFTER UPDATE ON auction_admin_actions BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=OLD.auction_id UNION SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=NEW.auction_id); END;
CREATE TRIGGER raid_revision_auction_admin_actions_delete AFTER DELETE ON auction_admin_actions BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_deletion_auctions WHERE auction_id=OLD.auction_id); END;
CREATE TRIGGER raid_revision_capture_sessions_insert AFTER INSERT ON capture_sessions BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT NEW.raid_id UNION SELECT raid_id FROM loot_drafts WHERE id=NEW.draft_id); END;
CREATE TRIGGER raid_revision_capture_sessions_update AFTER UPDATE ON capture_sessions BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT OLD.raid_id UNION SELECT raid_id FROM loot_drafts WHERE id=OLD.draft_id UNION SELECT NEW.raid_id UNION SELECT raid_id FROM loot_drafts WHERE id=NEW.draft_id); END;
CREATE TRIGGER raid_revision_capture_sessions_delete AFTER DELETE ON capture_sessions BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT OLD.raid_id UNION SELECT raid_id FROM loot_drafts WHERE id=OLD.draft_id); END;
CREATE TRIGGER raid_revision_capture_events_insert AFTER INSERT ON capture_events BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM capture_sessions WHERE id=NEW.capture_id); END;
CREATE TRIGGER raid_revision_capture_events_update AFTER UPDATE ON capture_events BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM capture_sessions WHERE id=OLD.capture_id UNION SELECT raid_id FROM capture_sessions WHERE id=NEW.capture_id); END;
CREATE TRIGGER raid_revision_capture_events_delete AFTER DELETE ON capture_events BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM capture_sessions WHERE id=OLD.capture_id); END;
CREATE TRIGGER raid_revision_raid_loot_imports_insert AFTER INSERT ON raid_loot_imports BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT NEW.raid_id); END;
CREATE TRIGGER raid_revision_raid_loot_imports_update AFTER UPDATE ON raid_loot_imports BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT OLD.raid_id UNION SELECT NEW.raid_id); END;
CREATE TRIGGER raid_revision_raid_loot_imports_delete AFTER DELETE ON raid_loot_imports BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT OLD.raid_id); END;
CREATE TRIGGER raid_revision_raid_loot_import_groups_insert AFTER INSERT ON raid_loot_import_groups BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_loot_imports WHERE id=NEW.import_id UNION SELECT raid_id FROM loot_drafts WHERE id=NEW.draft_id); END;
CREATE TRIGGER raid_revision_raid_loot_import_groups_update AFTER UPDATE ON raid_loot_import_groups BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_loot_imports WHERE id=OLD.import_id UNION SELECT raid_id FROM loot_drafts WHERE id=OLD.draft_id UNION SELECT raid_id FROM raid_loot_imports WHERE id=NEW.import_id UNION SELECT raid_id FROM loot_drafts WHERE id=NEW.draft_id); END;
CREATE TRIGGER raid_revision_raid_loot_import_groups_delete AFTER DELETE ON raid_loot_import_groups BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_loot_imports WHERE id=OLD.import_id UNION SELECT raid_id FROM loot_drafts WHERE id=OLD.draft_id); END;
CREATE TRIGGER raid_revision_raid_loot_import_links_insert AFTER INSERT ON raid_loot_import_links BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_loot_imports WHERE id=NEW.import_id UNION SELECT d.raid_id FROM raid_loot_import_groups g JOIN loot_drafts d ON d.id=g.draft_id WHERE g.id=NEW.group_id); END;
CREATE TRIGGER raid_revision_raid_loot_import_links_update AFTER UPDATE ON raid_loot_import_links BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_loot_imports WHERE id=OLD.import_id UNION SELECT d.raid_id FROM raid_loot_import_groups g JOIN loot_drafts d ON d.id=g.draft_id WHERE g.id=OLD.group_id UNION SELECT raid_id FROM raid_loot_imports WHERE id=NEW.import_id UNION SELECT d.raid_id FROM raid_loot_import_groups g JOIN loot_drafts d ON d.id=g.draft_id WHERE g.id=NEW.group_id); END;
CREATE TRIGGER raid_revision_raid_loot_import_links_delete AFTER DELETE ON raid_loot_import_links BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT raid_id FROM raid_loot_imports WHERE id=OLD.import_id UNION SELECT d.raid_id FROM raid_loot_import_groups g JOIN loot_drafts d ON d.id=g.draft_id WHERE g.id=OLD.group_id); END;
CREATE TRIGGER raid_revision_raid_loot_import_events_insert AFTER INSERT ON raid_loot_import_events BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT i.raid_id FROM raid_loot_import_links l JOIN raid_loot_imports i ON i.id=l.import_id WHERE l.event_id=NEW.id UNION SELECT d.raid_id FROM raid_loot_import_groups g JOIN loot_drafts d ON d.id=g.draft_id WHERE g.id=NEW.handoff_group_id); END;
CREATE TRIGGER raid_revision_raid_loot_import_events_update AFTER UPDATE ON raid_loot_import_events BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT i.raid_id FROM raid_loot_import_links l JOIN raid_loot_imports i ON i.id=l.import_id WHERE l.event_id=OLD.id UNION SELECT d.raid_id FROM raid_loot_import_groups g JOIN loot_drafts d ON d.id=g.draft_id WHERE g.id=OLD.handoff_group_id UNION SELECT i.raid_id FROM raid_loot_import_links l JOIN raid_loot_imports i ON i.id=l.import_id WHERE l.event_id=NEW.id UNION SELECT d.raid_id FROM raid_loot_import_groups g JOIN loot_drafts d ON d.id=g.draft_id WHERE g.id=NEW.handoff_group_id); END;
CREATE TRIGGER raid_revision_raid_loot_import_events_delete AFTER DELETE ON raid_loot_import_events BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT i.raid_id FROM raid_loot_import_links l JOIN raid_loot_imports i ON i.id=l.import_id WHERE l.event_id=OLD.id UNION SELECT d.raid_id FROM raid_loot_import_groups g JOIN loot_drafts d ON d.id=g.draft_id WHERE g.id=OLD.handoff_group_id); END;
CREATE TRIGGER raid_revision_attendance_tick_clones_insert AFTER INSERT ON attendance_tick_clones BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT NEW.raid_id); END;
CREATE TRIGGER raid_revision_attendance_tick_clones_update AFTER UPDATE ON attendance_tick_clones BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT OLD.raid_id UNION SELECT NEW.raid_id); END;
CREATE TRIGGER raid_revision_attendance_tick_clones_delete AFTER DELETE ON attendance_tick_clones BEGIN UPDATE raids SET revision=revision+1 WHERE id IN(SELECT OLD.raid_id); END;
CREATE TABLE raid_delete_targets (operation_id TEXT NOT NULL REFERENCES raid_delete_context(operation_id),kind TEXT NOT NULL,id TEXT NOT NULL,PRIMARY KEY(operation_id,kind,id));
CREATE VIEW raid_deletion_captures AS SELECT raid_id,id AS capture_id FROM capture_sessions WHERE raid_id IS NOT NULL UNION SELECT d.raid_id,c.id FROM capture_sessions c JOIN loot_drafts d ON d.id=c.draft_id WHERE d.raid_id IS NOT NULL;
CREATE VIEW raid_deletion_groups AS SELECT i.raid_id,g.id AS group_id FROM raid_loot_import_groups g JOIN raid_loot_imports i ON i.id=g.import_id WHERE i.raid_id IS NOT NULL UNION SELECT d.raid_id,g.id FROM raid_loot_import_groups g JOIN loot_drafts d ON d.id=g.draft_id WHERE d.raid_id IS NOT NULL;
CREATE TRIGGER raid_delete_context_loot_permission BEFORE INSERT ON raid_delete_context WHEN (EXISTS(SELECT 1 FROM loot_drafts WHERE raid_id=NEW.raid_id) OR EXISTS(SELECT 1 FROM raid_loot_imports WHERE raid_id=NEW.raid_id) OR EXISTS(SELECT 1 FROM raid_deletion_groups WHERE raid_id=NEW.raid_id)) AND NOT EXISTS(SELECT 1 FROM access_effective_permissions WHERE user_id=NEW.actor_id AND json_type(permissions_json,'$.loot')='integer' AND json_extract(permissions_json,'$.loot')=3) BEGIN SELECT RAISE(ABORT,'RAID_DELETE_SCOPE_DENIED'); END;
CREATE TRIGGER raid_delete_context_auction_permission BEFORE INSERT ON raid_delete_context WHEN EXISTS(SELECT 1 FROM raid_deletion_auctions WHERE raid_id=NEW.raid_id) AND NOT EXISTS(SELECT 1 FROM access_effective_permissions WHERE user_id=NEW.actor_id AND json_type(permissions_json,'$.auctionAdmin')='integer' AND json_extract(permissions_json,'$.auctionAdmin')=3) BEGIN SELECT RAISE(ABORT,'RAID_DELETE_SCOPE_DENIED'); END;
CREATE TRIGGER raid_delete_context_capture_permission BEFORE INSERT ON raid_delete_context WHEN EXISTS(SELECT 1 FROM raid_deletion_captures WHERE raid_id=NEW.raid_id) AND NOT EXISTS(SELECT 1 FROM access_effective_permissions WHERE user_id=NEW.actor_id AND json_type(permissions_json,'$.captures')='integer' AND json_extract(permissions_json,'$.captures')=3) BEGIN SELECT RAISE(ABORT,'RAID_DELETE_SCOPE_DENIED'); END;
